// Simple client‑side router based on location.pathname
const API_BASE = '/api';

function $(selector) {
  return document.querySelector(selector);
}

function createAlert(message) {
  const el = document.createElement('div');
  el.className = 'alert';
  el.textContent = message;
  return el;
}

async function fetchJSON(url, options = {}) {
  const resp = await fetch(url, { headers: { 'Content-Type': 'application/json' }, ...options });
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({}));
    throw new Error(err.error || resp.statusText);
  }
  return resp.json();
}

function renderProjectList() {
  const container = $('#app');
  container.innerHTML = '';
  const heading = document.createElement('h1');
  heading.textContent = 'Workboard';
  container.appendChild(heading);

  const form = document.createElement('div');
  const input = document.createElement('input');
  input.type = 'text';
  input.placeholder = 'Project name';
  input.setAttribute('aria-label', 'Project name');
  const btn = document.createElement('button');
  btn.textContent = 'Create project';
  form.appendChild(input);
  form.appendChild(btn);
  container.appendChild(form);

  const alertPlaceholder = document.createElement('div');
  container.appendChild(alertPlaceholder);

  btn.addEventListener('click', async () => {
    const name = input.value.trim();
    alertPlaceholder.innerHTML = '';
    if (!name) {
      alertPlaceholder.appendChild(createAlert('Project name is required'));
      return;
    }
    try {
      await fetchJSON(`${API_BASE}/projects`, {
        method: 'POST',
        body: JSON.stringify({ name })
      });
      input.value = '';
      await loadProjects();
    } catch (e) {
      alertPlaceholder.appendChild(createAlert(e.message));
    }
  });

  const list = document.createElement('div');
  container.appendChild(list);

  async function loadProjects() {
    const projects = await fetchJSON(`${API_BASE}/projects`);
    list.innerHTML = '';
    projects.forEach(p => {
      const row = document.createElement('div');
      row.className = 'row';
      row.dataset.testid = 'project-row';
      const nameSpan = document.createElement('span');
      nameSpan.textContent = p.name;
      const openBtn = document.createElement('button');
      openBtn.textContent = 'Open project';
      openBtn.addEventListener('click', () => {
        history.pushState(null, '', `/projects/${p.id}`);
        renderProjectPage(p.id);
      });
      row.appendChild(nameSpan);
      row.appendChild(openBtn);
      list.appendChild(row);
    });
  }

  loadProjects();
}

async function renderProjectPage(projectId) {
  const container = $('#app');
  container.innerHTML = '';
  // Fetch project details for heading
  const project = await fetchJSON(`${API_BASE}/projects/${projectId}`);
  const heading = document.createElement('h1');
  heading.textContent = project.name;
  container.appendChild(heading);

  const backBtn = document.createElement('button');
  backBtn.textContent = 'Projects';
  backBtn.addEventListener('click', () => {
    history.pushState(null, '', '/');
    renderProjectList();
  });
  container.appendChild(backBtn);

  // Task creation UI
  const taskForm = document.createElement('div');
  const taskInput = document.createElement('input');
  taskInput.type = 'text';
  taskInput.placeholder = 'Task title';
  taskInput.setAttribute('aria-label', 'Task title');
  const taskBtn = document.createElement('button');
  taskBtn.textContent = 'Create task';
  taskForm.appendChild(taskInput);
  taskForm.appendChild(taskBtn);
  container.appendChild(taskForm);

  const taskAlert = document.createElement('div');
  container.appendChild(taskAlert);

  // Filter combobox
  const filterDiv = document.createElement('div');
  const filterLabel = document.createElement('label');
  filterLabel.textContent = 'Task filter';
  const filterSelect = document.createElement('select');
  ['All', 'Open', 'Completed'].forEach(opt => {
    const o = document.createElement('option');
    o.value = opt.toLowerCase();
    o.textContent = opt;
    filterSelect.appendChild(o);
  });
  filterDiv.appendChild(filterLabel);
  filterDiv.appendChild(filterSelect);
  container.appendChild(filterDiv);

  const taskList = document.createElement('div');
  container.appendChild(taskList);

  let allTasks = [];

  async function loadTasks() {
    const tasks = await fetchJSON(`${API_BASE}/projects/${projectId}/tasks`);
    allTasks = tasks;
    renderTasks();
  }

  function renderTasks() {
    const filter = filterSelect.value; // all/open/completed
    taskList.innerHTML = '';
    allTasks
      .filter(t => {
        if (filter === 'open') return t.completed === 0;
        if (filter === 'completed') return t.completed === 1;
        return true;
      })
      .forEach(t => {
        const row = document.createElement('div');
        row.className = 'row';
        row.dataset.testid = 'task-row';
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = t.completed === 1;
        checkbox.setAttribute('aria-label', `Complete ${t.title}`);
        checkbox.addEventListener('change', async () => {
          await fetch(`${API_BASE}/tasks/${t.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked })
          });
          await loadTasks();
        });
        const span = document.createElement('span');
        span.textContent = t.title;
        row.appendChild(checkbox);
        row.appendChild(span);
        taskList.appendChild(row);
      });
  }

  taskBtn.addEventListener('click', async () => {
    const title = taskInput.value.trim();
    taskAlert.innerHTML = '';
    if (!title) {
      taskAlert.appendChild(createAlert('Task title is required'));
      return;
    }
    try {
      await fetchJSON(`${API_BASE}/projects/${projectId}/tasks`, {
        method: 'POST',
        body: JSON.stringify({ title })
      });
      taskInput.value = '';
      await loadTasks();
    } catch (e) {
      taskAlert.appendChild(createAlert(e.message));
    }
  });

  filterSelect.addEventListener('change', renderTasks);

  await loadTasks();
}

// Initial render based on current URL
function init() {
  if (location.pathname.startsWith('/projects/')) {
    const id = location.pathname.split('/')[2];
    renderProjectPage(id);
  } else {
    renderProjectList();
  }
}

window.addEventListener('popstate', init);
init();

import http from 'node:http';
import { URL } from 'node:url';
import path from 'node:path';
import fs from 'node:fs/promises';
import { createRequire } from 'node:module';
import sqlite from 'node:sqlite';

const require = createRequire(import.meta.url);

const PORT = process.env.PORT ? Number(process.env.PORT) : 8080;
const DB_PATH = process.env.DB_PATH || path.join(process.cwd(), 'workboard.db');

// Initialize SQLite database using the experimental synchronous API.
const { DatabaseSync } = sqlite;
const db = new DatabaseSync(DB_PATH);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`);

const PUBLIC_DIR = path.join(process.cwd(), 'public');

// Helper to serve static files
async function serveStatic(filePath, res) {
  try {
    const data = await fs.readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();
    const mime = {
      '.html': 'text/html',
      '.js': 'application/javascript',
      '.css': 'text/css',
      '.json': 'application/json',
    }[ext] || 'application/octet-stream';
    res.writeHead(200, { 'Content-Type': mime });
    res.end(data);
  } catch (e) {
    res.writeHead(404);
    res.end('Not found');
  }
}

// Simple JSON body parser
async function parseJson(req) {
  const chunks = [];
  for await (const chunk of req) {
    chunks.push(chunk);
  }
  const raw = Buffer.concat(chunks).toString();
  return raw ? JSON.parse(raw) : {};
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const pathname = url.pathname;

  // Health endpoint
  if (pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }

  // API routes under /api/
  if (pathname.startsWith('/api/')) {
    // Enable CORS for local testing
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PATCH,OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }

    // /api/projects
    if (pathname === '/api/projects') {
        if (req.method === 'GET') {
        const rows = db.prepare('SELECT id, name FROM projects ORDER BY id').all();
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(rows));
        return;
      }
      if (req.method === 'POST') {
        const { name } = await parseJson(req);
        const trimmed = (name || '').trim();
        if (!trimmed) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Project name is required' }));
          return;
        }
        const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(trimmed);
        const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(result.lastInsertRowid);
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(project));
        return;
      }
    }

    // /api/projects/:id/tasks and /api/projects/:id
    const projectIdMatch = pathname.match(/^\/api\/projects\/(\d+)(?:\/tasks)?$/);
    if (projectIdMatch) {
      const projectId = Number(projectIdMatch[1]);
      if (pathname.endsWith('/tasks')) {
        if (req.method === 'GET') {
          const stmt = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
          const tasks = stmt.all(projectId);
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify(tasks));
          return;
        }
        if (req.method === 'POST') {
          const { title } = await parseJson(req);
          const trimmed = (title || '').trim();
          if (!trimmed) {
            res.writeHead(400, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ error: 'Task title is required' }));
            return;
          }
          db.prepare('INSERT INTO tasks (project_id, title, completed) VALUES (?,?,0)')
            .run(projectId, trimmed);
          const tasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id')
            .all(projectId);
          res.writeHead(201, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify(tasks));
          return;
        }
      } else {
        // GET single project (used for heading)
        if (req.method === 'GET') {
          const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(projectId);
          if (!project) {
            res.writeHead(404, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ error: 'Project not found' }));
            return;
          }
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify(project));
          return;
        }
      }
    }

    // PATCH task completion
    const taskPatchMatch = pathname.match(/^\/api\/tasks\/(\d+)$/);
    if (taskPatchMatch && req.method === 'PATCH') {
      const taskId = Number(taskPatchMatch[1]);
      const { completed } = await parseJson(req);
      const completedInt = completed ? 1 : 0;
      db.prepare('UPDATE tasks SET completed = ? WHERE id = ?').run(completedInt, taskId);
      res.writeHead(200);
      res.end();
      return;
    }

    // Unknown API route
    res.writeHead(404);
    res.end('Not found');
    return;
  }

  // Serve static files. For any non-API path, fallback to index.html (client‑side routing)
  if (pathname === '/' || pathname.startsWith('/projects')) {
    await serveStatic(path.join(PUBLIC_DIR, 'index.html'), res);
    return;
  }

  // Attempt to serve the exact file from public
  const filePath = path.join(PUBLIC_DIR, pathname);
  await serveStatic(filePath, res);
});

server.listen(PORT, '0.0.0.0', () => {
  console.log(`Server listening on http://0.0.0.0:${PORT}`);
});
